module PokenomGo (\n    input clk,\n    input rst_n,\n    input start,\n    input query_type,\n    input [3:0] u,\n    input [3:0] v,\n    output reg [31:0] result,\n    output reg done\n);\n\nlocalparam MOD = 32'd1000000007;\nlocalparam N = 4'd8;\n\nreg [31:0] e_i [0:7];\nreg [31:0] e2_i [0:7];\nreg [31:0] e_ij [0:7][0:7];\n\nreg [3:0] L;\nreg [31:0] inv_L;\n\ninteger i, j, k;\n\nalways @* begin\n    L = v - u + 4'd1;\n    case(L)\n        4'd1: inv_L = 32'd1;\n        4'd2: inv_L = 32'd500000004;\n        4'd3: inv_L = 32'd333333336;\n        4'd4: inv_L = 32'd250000002;\n        4'd5: inv_L = 32'd400000003;\n        4'd6: inv_L = 32'd166666668;\n        4'd7: inv_L = 32'd142857144;\n        4'd8: inv_L = 32'd125000001;\n        default: inv_L = 32'd0;\n    endcase\nend\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        done <= 1'b0;\n        result <= 32'd0;\n        for (i = 0; i < N; i = i + 1) begin\n            e_i[i] <= 32'd0;\n            e2_i[i] <= 32'd0;\n            for (j = 0; j < N; j = j + 1) begin\n                e_ij[i][j] <= 32'd0;\n            end\n        end\n    end else begin\n        done <= 1'b0;\n        if (start) begin\n            if (!query_type) begin\n                for (i = 0; i < N; i = i + 1) begin\n                    if (i+1 >= u && i+1 <= v) begin\n                        e_i[i] <= (e_i[i] + inv_L) % MOD;\n                        e2_i[i] <= (e2_i[i] + ((64'd2 * inv_L * e_i[i]) % MOD) + inv_L) % MOD;\n                    end\n                    \n                    for (j = 0; j < N; j = j + 1) begin\n                        if (i != j) begin\n                            if ((j+1 >= u && j+1 <= v)) begin\n                                e_ij[i][j] <= (e_ij[i][j] + inv_L * e_i[i]) % MOD;\n                            end\n                            if ((i+1 >= u && i+1 <= v)) begin\n                                e_ij[i][j] <= (e_ij[i][j] + inv_L * e_i[j]) % MOD;\n                            end\n                        end\n                    end\n                end\n            end else begin\n                result <= 32'd0;\n                for (k = 0; k < N; k = k + 1) begin\n                    result <= (result + e2_i[k]) % MOD;\n                end\n                done <= 1'b1;\n            end\n        end\n    end\nend\n\nendmodule